// Uses the independent preimplementation Unicode coordinate table, loaded as
// generated Rust literals below. The candidate computes no expected locations.
#[test]
fn independent_unit2d_checkpoint1_coordinate_oracle() {
    let source_rows: &[(&str,&str)] = INDEPENDENT_UNIT2D_SOURCES;
    let coordinates: &[(usize,usize,usize,usize)] = INDEPENDENT_UNIT2D_COORDINATES;
    let mut sources=SourceMap::new();for (path,text) in source_rows {sources.add((*path).into(),(*text).into());}
    let mut order:Vec<_>=(0..coordinates.len()).map(|i|coordinates[(i*37)%coordinates.len()]).collect();
    order.extend_from_within(0..20);
    let mut functions=vec![];
    for (function_index,chunk) in order.chunks(120).enumerate() {
        let (file,start,_,_)=chunk[0];let span=Span{file:crate::frontend::source::SourceFileId(file),start,end:start};
        let mut f=fixtures::function(function_index,ValueTy::Scalar(hir::Ty::I32),span);
        f.locals=(0..chunk.len()+2).map(|_|fixtures::scalar(hir::Ty::I32,span)).collect();
        let mut body=vec![fixtures::assign(0,Rvalue::I32(0),span),fixtures::assign(1,Rvalue::I32(1),span)];
        for (i,&(file,start,_,_)) in chunk.iter().enumerate(){let at=Span{file:crate::frontend::source::SourceFileId(file),start,end:start};body.push(fixtures::assign(i+2,Rvalue::CheckedI32{op:hir::ArithmeticOp::Add,left:fixtures::operand(0,at),right:fixtures::operand(1,at),operator_span:at},at));}
        f.blocks.push(block(body,OwnedTerminatorKind::ReturnScalar(fixtures::operand(chunk.len()+1,span)),span));functions.push(f);
    }
    let witness=verified::verify_owned(RawOwnedProgram{records:vec![],functions},&sources).unwrap();
    let plan=ExecutionPlan::build(&witness).unwrap();let mut accounting=Accounting::default();
    let diagnostics=Diagnostics::new_accounted(&plan,hir::DefId(0),&sources,false,MAX_DIAGNOSTIC_BYTES,plan::MAX_PLAN_BYTES,&mut accounting).unwrap();
    assert_eq!(accounting.metrics.occurrences,739);assert_eq!(accounting.metrics.unique,719);
    assert_eq!(accounting.metrics.occurrence_bytes,739*64);
    assert_eq!(accounting.metrics.source_prefix_bound,INDEPENDENT_UNIT2D_SOURCE_BYTES);assert_eq!(accounting.metrics.source_bytes,INDEPENDENT_UNIT2D_SOURCE_BYTES);
    assert_eq!(accounting.metrics.source_scalars,715);
    assert_eq!(accounting.metrics.prefix_preflight_rows,719);assert_eq!(accounting.metrics.coordinate_rows,719);
    for (id,&(file,start,line,column)) in order[..719].iter().enumerate(){
        let path=source_rows[file].0;let escaped:String=path.chars().flat_map(|c|if c.is_control(){c.escape_default().collect::<Vec<_>>()}else{vec![c]}).collect();
        let expected=format!("error[E0604] (oir-run): checked i32 arithmetic overflow\n  --> {escaped}:{line}:{column}\n");
        assert_eq!(diagnostics.messages[id],expected,"file={file},start={start}");
        let span=Span{file:crate::frontend::source::SourceFileId(file),start,end:start};assert_eq!(diagnostics.get(FailureKind::Overflow,span).0,id);
    }
    eprintln!("independent checkpoint1 Unicode oracle:739 occurrences,719 unique full keys; prefix bytes={},scalars=715",INDEPENDENT_UNIT2D_SOURCE_BYTES);
}

